// ClassifyAsset embebido (ver docs/anexo_e_f_v2.md para la justificacion de pesos)
const SERVICE_WEIGHTS = {
  21: 7, 22: 9, 23: 12, 25: 4, 80: 5, 161: 6, 389: 7, 443: 4,
  445: 8, 587: 4, 3306: 10, 5432: 10, 6379: 10, 8080: 5,
};

function classifyAsset(openPorts) {
  const score = (openPorts || []).reduce((sum, port) => sum + (SERVICE_WEIGHTS[port] || 1), 0);
  let classification;
  if (score > 20) classification = 'Critico';
  else if (score > 10) classification = 'Alto';
  else classification = 'Normal';
  return { score, classification };
}

const raw = items[0].json;
// n8n guarda el body bajo $json.body cuando recibe application/json
const payload = raw.hosts !== undefined ? raw : raw.body !== undefined ? raw.body : raw;
const hostsRaw = Array.isArray(payload.hosts) ? payload.hosts : [];

const ignoradas = ["172.20.0.1", "172.20.0.2", "172.20.0.3"];

// Soporta formato viejo (array de strings, solo IP) y nuevo (array de {ip, ports})
// para no romper compatibilidad si algun caller viejo todavia manda solo IPs.
const hosts = hostsRaw
  .map(h => (typeof h === 'string') ? { ip: h, ports: [] } : h)
  .filter(h => h && h.ip && ignoradas.indexOf(h.ip) === -1);

const clasificados = hosts.map(h => {
  const { score, classification } = classifyAsset(h.ports);
  return { ip: h.ip, ports: h.ports || [], score, classification };
});

